export function applyLevelContent(levels) {
  for (const lv of levels) { const t = LEVEL_TEXT[lv.id]; if (t && t.length) lv.words = t; }
  const have = new Set(levels.map(l => l.id));
  for (const e of EXTRA_LEVELS) if (!have.has(e.id)) levels.push({ ...e });
  return levels;
}

// Apply admin-chosen level names (id -> name). Original names are remembered so removing an override restores them.
export function applyLevelNames(levels, names) {
  for (const l of levels) {
    if (l.__origName === undefined) l.__origName = l.name;
    const n = names && names[String(l.id)];
    l.name = n || l.__origName;
  }
}
